Query#1: WITH p AS (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) SELECT sum(calc.l_extendedprice) / ^^^_A AS avg_yearly FROM (SELECT l.l_extendedprice, l.l_quantity, avg(l.l_quantity) OVER (PARTITION BY l.l_partkey) AS avg_q FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey) calc WHERE calc.l_quantity < ^^^_B * calc.avg_q;
Query#2: SELECT sum(calc.l_extendedprice) / ^^^_A AS avg_yearly FROM (SELECT l.l_extendedprice, l.l_quantity, avg(l.l_quantity) OVER (PARTITION BY l.l_partkey) AS avg_q FROM lineitem l JOIN (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) p ON l.l_partkey = p.p_partkey) calc WHERE calc.l_quantity < ^^^_B * calc.avg_q;
Query#3: WITH p AS (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) SELECT sum(calc.l_extendedprice) / ^^^_A AS avg_yearly FROM (SELECT l.l_extendedprice, l.l_quantity, ^^^_B * avg(l.l_quantity) OVER (PARTITION BY l.l_partkey) AS threshold FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey) calc WHERE calc.l_quantity < calc.threshold;
Query#4: SELECT sum(calc.l_extendedprice) / ^^^_A AS avg_yearly FROM (SELECT l.l_extendedprice, l.l_quantity, ^^^_B * avg(l.l_quantity) OVER (PARTITION BY l.l_partkey) AS threshold FROM lineitem l JOIN part p ON l.l_partkey = p.p_partkey WHERE p.p_brand = &&&_A AND p.p_container = &&&_B) calc WHERE calc.l_quantity < calc.threshold;
Query#5: SELECT sum(calc.l_extendedprice) / ^^^_A AS avg_yearly FROM (SELECT l.l_extendedprice, l.l_quantity, avg(l.l_quantity) OVER (PARTITION BY l.l_partkey) AS avg_q FROM lineitem l INNER JOIN part p ON l.l_partkey = p.p_partkey WHERE p.p_brand = &&&_A AND p.p_container = &&&_B) calc WHERE calc.l_quantity < ^^^_B * calc.avg_q;
Query#6: WITH p AS (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B), part_avg AS (SELECT l.l_partkey, ^^^_B * avg(l.l_quantity) AS threshold FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey GROUP BY l.l_partkey) SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey JOIN part_avg pa ON l.l_partkey = pa.l_partkey WHERE l.l_quantity < pa.threshold;
Query#7: WITH p AS (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B), part_avg AS MATERIALIZED (SELECT l.l_partkey, ^^^_B * avg(l.l_quantity) AS threshold FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey GROUP BY l.l_partkey) SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey JOIN part_avg pa ON l.l_partkey = pa.l_partkey WHERE l.l_quantity < pa.threshold;
Query#8: SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) p ON l.l_partkey = p.p_partkey JOIN (SELECT l2.l_partkey, ^^^_B * avg(l2.l_quantity) AS threshold FROM lineitem l2 JOIN part p2 ON l2.l_partkey = p2.p_partkey WHERE p2.p_brand = &&&_A AND p2.p_container = &&&_B GROUP BY l2.l_partkey) pa ON l.l_partkey = pa.l_partkey WHERE l.l_quantity < pa.threshold;
Query#9: WITH part_avg AS (SELECT l_partkey, ^^^_B * avg(l_quantity) AS threshold FROM lineitem GROUP BY l_partkey) SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN part p ON l.l_partkey = p.p_partkey JOIN part_avg pa ON l.l_partkey = pa.l_partkey WHERE p.p_brand = &&&_A AND p.p_container = &&&_B AND l.l_quantity < pa.threshold;
Query#10: SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN part p ON l.l_partkey = p.p_partkey JOIN (SELECT l_partkey, ^^^_B * avg(l_quantity) AS threshold FROM lineitem GROUP BY l_partkey) pa ON l.l_partkey = pa.l_partkey WHERE p.p_brand = &&&_A AND p.p_container = &&&_B AND l.l_quantity < pa.threshold;
Query#11: WITH p AS (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN p ON l.l_partkey = p.p_partkey WHERE l.l_quantity < (SELECT ^^^_B * avg(l2.l_quantity) FROM lineitem l2 WHERE l2.l_partkey = l.l_partkey);
Query#12: SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM lineitem l JOIN (SELECT p_partkey FROM part WHERE p_brand = &&&_A AND p_container = &&&_B) p ON l.l_partkey = p.p_partkey WHERE l.l_quantity < (SELECT ^^^_B * avg(l2.l_quantity) FROM lineitem l2 WHERE l2.l_partkey = p.p_partkey);
Query#13: SELECT sum(l.l_extendedprice) / ^^^_A AS avg_yearly FROM part p JOIN lineitem l ON p.p_partkey = l.l_partkey CROSS JOIN LATERAL (SELECT ^^^_B * avg(l_quantity) AS threshold FROM lineitem l2 WHERE l2.l_partkey = p.p_partkey) pa WHERE p.p_brand = &&&_A AND p.p_container = &&&_B AND l.l_quantity < pa.threshold;
